/**
 * FRONTEO 3D OBJECT VIEWER
 * Authentic Fusion 360 FBX export with exact materials and colors
 */

(function () {
  'use strict';

  const FRONTEO_GLB_BASE64 = "";

  function base64ToArrayBuffer(base64) {
    const binaryString = window.atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes.buffer;
  }

  function initFronteo3D() {
    const container = document.getElementById('fronteo-3d-wrapper');
    const canvas = document.getElementById('fronteo-3d-canvas');
    if (!container || !canvas || typeof THREE === 'undefined') return;

    container.style.setProperty('background', 'transparent', 'important');
    container.style.setProperty('background-color', 'transparent', 'important');
    container.style.setProperty('background-image', 'none', 'important');
    container.style.setProperty('border', 'none', 'important');
    container.style.setProperty('box-shadow', 'none', 'important');
    canvas.style.setProperty('background', 'transparent', 'important');
    canvas.style.setProperty('background-color', 'transparent', 'important');

    // ==========================================================================
    // PARÁMETROS CONFIGURABLES DE TAMAÑO, POSICIÓN Y VELOCIDAD 3D
    // ==========================================================================
    const CONFIG = {
      targetDim: 11.5,        // TAMAÑO: Escala monumental, desborde libre sin cortes
      positionX: 0.0,         // POSICIÓN HORIZONTAL: desplazado a la derecha
      positionY: 0.0,         // POSICIÓN VERTICAL: 0 = centrado
      positionZ: 0.0,         // PROFUNDIDAD
      cameraDistance: 12.5,   // DISTANCIA DE CÁMARA
      rotationSeconds: 4.0    // VELOCIDAD: Segundos por cada giro de 360°
    };

    // 1. Scene & Camera Setup
    const scene = new THREE.Scene();

    const fov = 34;
    function getContainerSize() {
      const rect = container.getBoundingClientRect();
      const canvasRect = canvas.getBoundingClientRect();
      const w = canvasRect.width || rect.width || container.clientWidth || 1000;
      const h = canvasRect.height || rect.height || Math.round(window.innerHeight * 0.40) || 400;
      return { w: Math.max(w, 100), h: Math.max(h, 100) };
    }

    function updateCameraProportions(w, h) {
      camera.aspect = w / h;
      const isMobile = w < 768;
      const desiredFillRatio = isMobile ? 0.84 : 0.48;
      const tanHalfFov = Math.tan((fov * Math.PI) / 360);
      const idealZ = 11.5 / (desiredFillRatio * 2 * tanHalfFov * (w / h));
      const targetZ = isMobile ? Math.max(7.0, Math.min(idealZ, 11.5)) : CONFIG.cameraDistance;
      camera.position.set(0, 0, targetZ);
      camera.updateProjectionMatrix();
    }

    let size = getContainerSize();
    const camera = new THREE.PerspectiveCamera(fov, size.w / size.h, 0.1, 100);
    updateCameraProportions(size.w, size.h);

    // 2. WebGL Renderer
    const renderer = new THREE.WebGLRenderer({
      canvas: canvas,
      alpha: true,
      antialias: true,
      powerPreference: 'high-performance'
    });
    renderer.setSize(size.w, size.h);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setClearColor(0x000000, 0);

    if (renderer.outputColorSpace) {
      renderer.outputColorSpace = THREE.SRGBColorSpace;
    } else if (renderer.outputEncoding) {
      renderer.outputEncoding = THREE.sRGBEncoding;
    }
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 0.88;

    // 3. High-Contrast Studio Lighting Rig
    // Subtle ambient light to keep dark bevels deep and rich
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.28);
    scene.add(ambientLight);

    // Key directional light for crisp highlights and rich 3D shading
    const keyLight = new THREE.DirectionalLight(0xffffff, 1.15);
    keyLight.position.set(-2.5, 5.5, 4.5);
    scene.add(keyLight);

    // Cool subtle fill light for contrast
    const fillLight = new THREE.DirectionalLight(0x7090b8, 0.45);
    fillLight.position.set(3.5, 2.0, 3.5);
    scene.add(fillLight);

    // Soft rim light
    const rimLight = new THREE.DirectionalLight(0xddeeff, 0.65);
    rimLight.position.set(0, -3.5, -3.0);
    scene.add(rimLight);

    // 4. Transformation Groups
    const rootGroup = new THREE.Group();
    rootGroup.position.set(CONFIG.positionX, CONFIG.positionY, CONFIG.positionZ);
    scene.add(rootGroup);

    const modelGroup = new THREE.Group();
    rootGroup.add(modelGroup);

    function setupLoadedModel(rawScene) {
      const bbox = new THREE.Box3().setFromObject(rawScene);
      const center = new THREE.Vector3();
      const dims = new THREE.Vector3();
      bbox.getCenter(center);
      bbox.getSize(dims);

      // Center geometry at origin (0, 0, 0)
      rawScene.position.set(-center.x, -center.y, -center.z);

      // Scale model to fit comfortably without getting clipped
      const maxDim = Math.max(dims.x, dims.y * 2.5, dims.z);
      const targetDim = CONFIG.targetDim;
      const normalizedScale = targetDim / maxDim;

      modelGroup.scale.set(normalizedScale, normalizedScale, normalizedScale);
      modelGroup.add(rawScene);

      // Centrado exacto horizontal y vertical
      rootGroup.position.set(0.0, CONFIG.positionY, CONFIG.positionZ);

      // Calibrate physical materials for high contrast and rich saturation
      rawScene.traverse((child) => {
        if (child.isMesh && child.material) {
          const mat = child.material;
          const col = mat.color;
          
          if (col.g > 0.5 && col.r < 0.3) {
            // Cyan outline: vibrant electric cyan
            child.material = new THREE.MeshPhysicalMaterial({
              color: new THREE.Color(0.0, 0.78, 0.94),
              roughness: 0.22,
              metalness: 0.04,
              clearcoat: 0.85,
              clearcoatRoughness: 0.06,
              reflectivity: 0.75
            });
          } else if (col.r < 0.15 && col.g < 0.15 && col.b < 0.15) {
            // Inner stroke: deep rich jet black
            child.material = new THREE.MeshPhysicalMaterial({
              color: new THREE.Color(0.05, 0.06, 0.07),
              roughness: 0.25,
              metalness: 0.08,
              clearcoat: 0.9,
              clearcoatRoughness: 0.05,
              reflectivity: 0.8
            });
          } else {
            // Letter face: soft white ceramic with smooth shading
            child.material = new THREE.MeshPhysicalMaterial({
              color: new THREE.Color(0.92, 0.93, 0.95),
              roughness: 0.30,
              metalness: 0.02,
              clearcoat: 0.7,
              clearcoatRoughness: 0.08,
              reflectivity: 0.65
            });
          }
          child.material.needsUpdate = true;
        }
      });
    }

    // 5. Load GLB Model from Embedded Base64 (0 latency, 100% reliable)
    if (typeof THREE.GLTFLoader !== 'undefined') {
      const loader = new THREE.GLTFLoader();
      try {
        const arrayBuffer = base64ToArrayBuffer(FRONTEO_GLB_BASE64);
        loader.parse(arrayBuffer, '', function (gltf) {
          setupLoadedModel(gltf.scene);
        }, function (err) {
          console.error('Error parsing embedded GLB:', err);
          loader.load('../assets/models/fronteo.glb', function (gltf) {
            setupLoadedModel(gltf.scene);
          });
        });
      } catch (e) {
        console.warn('Base64 parse fallback:', e);
        loader.load('../assets/models/fronteo.glb', function (gltf) {
          setupLoadedModel(gltf.scene);
        });
      }
    }

    // 6. Resize Handling
    function handleResize() {
      if (!container || !renderer || !camera) return;
      const s = getContainerSize();
      updateCameraProportions(s.w, s.h);

      rootGroup.position.x = 0.0;

      renderer.setSize(s.w, s.h);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    }

    window.addEventListener('resize', handleResize);

    // 7. Precise 4.0-Second Full 360-Degree Rotation Loop
    const clock = new THREE.Clock();
    const FULL_ROTATION_SECONDS = 4.0; // exactly 4.0 seconds per complete 360-degree turn
    const ANGULAR_VELOCITY = (Math.PI * 2) / FULL_ROTATION_SECONDS; // ~1.5708 rad/sec

    let isVisible = true;
    document.addEventListener('visibilitychange', () => {
      isVisible = !document.hidden;
      if (isVisible) clock.getDelta(); // reset delta on tab reactivation
    });

    function animate() {
      requestAnimationFrame(animate);
      if (!isVisible) return;

      const delta = Math.min(clock.getDelta(), 0.1);
      rootGroup.rotation.y += delta * ANGULAR_VELOCITY;

      renderer.render(scene, camera);
    }

    animate();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initFronteo3D);
  } else {
    initFronteo3D();
  }
})();
